import React, { Component } from "react";
import { Col, Row, Table, Card, CardHeader, CardBody, CardGroup } from "reactstrap";
import { FormattedMessage } from "react-intl";
import Loader from "react-loader-spinner";

// redux
import { connect } from "react-redux";
import { bindActionCreators } from "redux";
import { fetchVisaAcquirerPostingSummaryValidated } from "../../../../actions/filesets";

// components
import Widget04 from "../../../../Utils/Widgets04";
import PostingTableHeader from "../../../../components/PostingTableHeader";
import PostingTable from "../../../../components/PostingTable";

class ValidatedEntries extends Component {
	constructor (props) {
		super(props);
		this.state = { selectedCode: "" };
	}

	static getDerivedStateFromProps (props, state) {
		if (props.selectedAffiliateCode !== state.selectedCode) {
			return {
				selectedCode : props.selectedAffiliateCode,
			};
		}

		// Return null if the state hasn't changed
		return null;
	}

	componentDidMount () {
		if (this.state.selectedCode) {
			this.props.fetchVisaAcquirerPostingSummaryValidated(this.props.match.params.date, this.state.selectedCode);
		}
	}

	componentDidUpdate (prevProps) {
		if (this.props.selectedAffiliateCode !== prevProps.selectedAffiliateCode) {
			this.props.fetchVisaAcquirerPostingSummaryValidated(this.props.match.params.date, this.state.selectedCode);
		}

		if (this.props.match.params.date !== prevProps.match.params.date) {
			this.props.fetchVisaAcquirerPostingSummaryValidated(this.props.match.params.date, this.state.selectedCode);
		}
	}

	render () {
		// setting the table header array to use with the reuable PostingTableHeader component
		// const headerPayload = [ "Account", "Description", "Credit", "Debit" ];

		return (
			<div className='animated fadeIn'>
				<Row>
					<Col>
						{!this.props.fileSets ? (
							<CardGroup className='mb-4'>
								<Widget04
									icon='icon-people'
									color='info'
									// header={this.props.fileSets.visaIssuerTransactions.data.totalElements.toLocaleString()} original!
									header='34'
									value='25'
								>
									Transactions
								</Widget04>
								<Widget04 icon='icon-user-follow' color='success' header='0' value='25'>
									Successful Transactions
								</Widget04>
								<Widget04 icon='icon-basket-loaded' color='warning' header='0' value='25'>
									Credits
								</Widget04>
								<Widget04 icon='icon-pie-chart' color='primary' header='0' value='5'>
									Debits
								</Widget04>
								<Widget04 icon='icon-speedometer' color='danger' header='0' value='25'>
									Amount
								</Widget04>
							</CardGroup>
						) : null}
					</Col>
				</Row>

				<Row>
					<Col xs='12' md='12' className='mb-4'>
						<Card>
							<CardHeader className={"d-flex justify-content-between align-items-center"}>
								<strong>Visa Posting {this.props.match.params.date} Summary</strong>
							</CardHeader>

							<CardBody>
								{/* Handle loading */}
								{!this.props.validatedEntries &&
								!this.props.validatedEntriesError && (
									<article className='d-flex justify-content-center align-items-center'>
										<Loader type='ThreeDots' color='#337AB7' height={100} width={100} />
									</article>
								)}

								{/* Handle Error */}
								{this.props.validatedEntriesError &&
								!this.props.validatedEntries && (
									<article className='text-danger text-danger d-flex justify-content-center align-items-center py-4'>
										<FormattedMessage
											id='Error unable to load entries'
											defaultMessage='Error unable to load entries'
										/>
									</article>
								)}

								{/* Handlde 404 Error */}
								{this.props.validatedEntries &&
								this.props.validatedEntries.length === 0 && (
									<article className='text-danger d-flex justify-content-center align-items-center'>
										<FormattedMessage
											id='No posting file for this date'
											defaultMessage='No posting file for this date'
										/>
									</article>
								)}

								{/* Handle display content */}
								{!this.props.validatedEntriesError &&
								this.props.validatedEntries &&
								this.props.validatedEntries.length > 0 && (
									<Table
										hover
										bordered
										striped
										responsive
										size='sm'
										className='table-outline mb-0 d-sm-table'
										style={{ minWidth: "180%" }}
									>
										<thead>
											<PostingTableHeader />
										</thead>
										<tbody>
											<PostingTable dataRecords={[ ...this.props.validatedEntries ]} />
										</tbody>
									</Table>
								)}
							</CardBody>
						</Card>
					</Col>
				</Row>
			</div>
		);
	}
}

const mapStateToProps = (state) => {
	return {
		selectedAffiliateCode : state.fileSets.selectedAffiliateCode,
		validatedEntries      : state.fileSets.validatedEntries,
		validatedEntriesError : state.fileSets.validatedEntriesError,
	};
};

const mapDispatchToProps = (dispatch) => {
	return bindActionCreators(
		{
			fetchVisaAcquirerPostingSummaryValidated,
		},
		dispatch,
	);
};

export default connect(mapStateToProps, mapDispatchToProps)(ValidatedEntries);
